    notes: "The Python Patrol repaint of Cobra's elite Crimson Guard, the Python Crimson Guard debuted in the 1989 Python Patrol subset wearing the line's signature black-and-silver urban-camo deco rather than the original red dress uniform; as a repaint of an already army-builder-favorite trooper, loose 1989 examples with the snake-pattern accessories command modest premiums among Python Patrol set-builders.",
