    notes: "Crazylegs is a GI Joe assault trooper and paratrooper whose file-card name is David L. Thomas, debuting in 1987 with a parachute pack and rifle; a relatively minor figure in the vintage run with limited cartoon presence, his collector interest grew with the modern Classified Series treatment, where the airborne specialist found new appreciation among completist fans.",
