    notes: "The Crimson Guard is Cobra's elite uniformed Siegie corps, debuting in 1985 in a striking red-and-gold dress uniform and serving as deep-cover operatives in the Marvel Comics and Sunbow fiction; one of the most beloved army-builder troops in the franchise, this Super7-style cartoon-accurate release targets collectors chasing animation-faithful deco, while vintage 1985 figures remain perennial multiples-buying favorites.",
