    notes: "Beachhead (Ranger) debuted in 1986 as the team's brutal drill-instructor and Ranger, his balaclava-masked head sculpt and backpack-mounted gear making him instantly recognizable; a standout in both the Marvel comics and Sunbow cartoon as the hard-nosed trainer, his original 1986 figure with the soft-goods balaclava and full accessory complement remains a steady mid-tier vintage want, with the 25th Anniversary update reintroducing him to modern collectors.",
