    notes: "One of Cobra's strangest entries, Crystal Ball was a hypnotist who debuted in 1987 with a flowing cape and an unsettling translucent-vac-metal face, his mind-control gimmick making him a cult oddity among Cobra collectors; the cape and unusual headsculpt define complete examples, and his bizarre design keeps him a frequently discussed vintage curiosity.",
